script:
employee = frappe.db.get_value("Employee", {"user_id": frappe.session.user}, "name")
holiday_list = None
if employee:
    holiday_list = frappe.db.get_value("Employee", employee, "holiday_list")
if not holiday_list:
    company = frappe.db.get_value("Employee", employee, "company") if employee else None
    if company:
        holiday_list = frappe.db.get_value("Company", company, "default_holiday_list")
if not holiday_list:
    holiday_list = frappe.db.get_value("Company", {}, "default_holiday_list")

from_date = frappe.form_dict.get("from_date")
to_date = frappe.form_dict.get("to_date")
out = []
if holiday_list:
    filters = {"parent": holiday_list}
    if from_date and to_date:
        filters["holiday_date"] = ["between", [from_date, to_date]]
    rows = frappe.get_all("Holiday", filters=filters,
                          fields=["holiday_date", "description", "weekly_off"],
                          limit_page_length=0, ignore_permissions=True)
    for r in rows:
        out.append({"date": str(r["holiday_date"]), "description": r["description"],
                    "weekly_off": r["weekly_off"]})
frappe.response["message"] = out
